import React, { useState } from "react";

const Login = () => {

  const [mobile, setMobile] = useState("");
  const [otp, setOtp] = useState("");
  const [generatedOTP, setGeneratedOTP] = useState("");
  const [showOTP, setShowOTP] = useState(false);
  const [loading, setLoading] = useState(false);
  const [message, setMessage] = useState("");

  // Send OTP
  const sendOTP = async () => {

    if (mobile.length !== 10 || isNaN(mobile)) {
      setMessage("Please enter valid mobile number");
      return;
    }

    setLoading(true);

    try {

      // DEMO OTP
      const demoOTP =
        Math.floor(100000 + Math.random() * 900000).toString();

      setGeneratedOTP(demoOTP);

      console.log("OTP:", demoOTP);

      // Backend connection example
      await fetch("http://localhost:5000/api/health");

      setShowOTP(true);

      setMessage(`OTP Sent Successfully`);

    } catch (err) {

      setMessage("Backend not connected");

    } finally {

      setLoading(false);
    }
  };

  // Verify OTP
  const verifyOTP = () => {

    if (otp === generatedOTP) {

      localStorage.setItem("userMobile", mobile);

      setMessage("Login Successful ✅");

      // Redirect
      window.location.href = "/";

    } else {

      setMessage("Invalid OTP ❌");
    }
  };

  return (

    <div style={styles.container}>

      <div style={styles.overlay}></div>

      <div style={styles.card}>

        <div style={styles.logo}>
          ⚖️
        </div>

        <h1 style={styles.title}>
          JusticeLens AI
        </h1>

        <p style={styles.subtitle}>
          Secure Login with OTP
        </p>

        <div style={styles.inputBox}>

          <span style={styles.countryCode}>
            +91
          </span>

          <input
            type="text"
            placeholder="Enter Mobile Number"
            value={mobile}
            maxLength={10}
            onChange={(e) => setMobile(e.target.value)}
            style={styles.input}
          />

        </div>

        {!showOTP && (

          <button
            style={styles.button}
            onClick={sendOTP}
            disabled={loading}
          >
            {loading ? "Sending OTP..." : "Send OTP"}
          </button>

        )}

        {showOTP && (

          <>
            <input
              type="text"
              placeholder="Enter OTP"
              value={otp}
              maxLength={6}
              onChange={(e) => setOtp(e.target.value)}
              style={styles.otpInput}
            />

            <button
              style={styles.button}
              onClick={verifyOTP}
            >
              Verify OTP
            </button>
          </>

        )}

        {message && (
          <p style={styles.message}>
            {message}
          </p>
        )}

        <p style={styles.footer}>
          AI Powered Legal Intelligence Platform
        </p>

      </div>

    </div>
  );
};

const styles = {

  container: {
    height: "100vh",
    width: "100%",
    display: "flex",
    justifyContent: "center",
    alignItems: "center",
    background:
      "linear-gradient(135deg, #0f172a, #1e3a8a, #312e81)",
    position: "relative",
    overflow: "hidden"
  },

  overlay: {
    position: "absolute",
    width: "600px",
    height: "600px",
    borderRadius: "50%",
    background: "rgba(255,255,255,0.05)",
    top: "-200px",
    right: "-200px"
  },

  card: {
    width: "380px",
    background: "rgba(255,255,255,0.1)",
    backdropFilter: "blur(15px)",
    border: "1px solid rgba(255,255,255,0.2)",
    borderRadius: "20px",
    padding: "40px 30px",
    color: "#fff",
    textAlign: "center",
    boxShadow: "0 10px 40px rgba(0,0,0,0.3)",
    zIndex: 2
  },

  logo: {
    fontSize: "55px",
    marginBottom: "10px"
  },

  title: {
    fontSize: "32px",
    marginBottom: "5px",
    fontWeight: "700"
  },

  subtitle: {
    color: "#d1d5db",
    marginBottom: "30px"
  },

  inputBox: {
    display: "flex",
    alignItems: "center",
    background: "rgba(255,255,255,0.12)",
    borderRadius: "12px",
    padding: "0 12px",
    marginBottom: "20px"
  },

  countryCode: {
    color: "#fff",
    fontWeight: "bold",
    marginRight: "8px"
  },

  input: {
    flex: 1,
    background: "transparent",
    border: "none",
    outline: "none",
    padding: "15px 10px",
    color: "#fff",
    fontSize: "16px"
  },

  otpInput: {
    width: "100%",
    padding: "15px",
    borderRadius: "12px",
    border: "none",
    outline: "none",
    marginBottom: "20px",
    background: "rgba(255,255,255,0.12)",
    color: "#fff",
    fontSize: "16px"
  },

  button: {
    width: "100%",
    padding: "15px",
    border: "none",
    borderRadius: "12px",
    background: "linear-gradient(90deg,#2563eb,#7c3aed)",
    color: "#fff",
    fontSize: "16px",
    fontWeight: "600",
    cursor: "pointer",
    transition: "0.3s",
    marginBottom: "15px"
  },

  message: {
    marginTop: "10px",
    color: "#facc15",
    fontWeight: "500"
  },

  footer: {
    marginTop: "25px",
    fontSize: "13px",
    color: "#cbd5e1"
  }
};

export default Login;
